/** Background colours for icon avatars; white on each is at least 4.5:1. */
export const AVATAR_COLORS = [
    '#2563eb',
    '#7c3aed',
    '#be185d',
    '#b91c1c',
    '#b45309',
    '#15803d',
    '#0f766e',
    '#475569'
] as const;

export const AVATAR_COLOR_NAMES = [
    'Blue',
    'Violet',
    'Pink',
    'Red',
    'Amber',
    'Green',
    'Teal',
    'Slate'
] as const;

export const avatarIconSchema = z.object({
    icon: z.string().refine((k) => AVATAR_ICONS.some((i) => i.key === k), 'Unknown icon'),
    color: z
        .number()
        .int()
        .min(0)
        .max(AVATAR_COLORS.length - 1)
});
/** A user's chosen icon avatar */
export type AvatarIconChoice = z.infer<typeof avatarIconSchema>;

export const findAvatarIcon = (key: string) => AVATAR_ICONS.find((i) => i.key === key);
